// Fonte Inter (OFL) embutida como Buffer/base64 para o resvg desenhar
// texto de forma independente do SO — o ambiente serverless da Vercel
// (Linux) não vem com NENHUMA fonte instalada, então o sharp/librsvg
// desenhava caixas no lugar de texto. resvg recebe a fonte via buffer
// (fontBuffers), sem depender de fontconfig/fontes do sistema.
export const FONT_FAMILY = "Inter";

export const FONT_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 500, data: "" },
  { weight: 600, data: "" },
  { weight: 800, data: "" },
  { weight: 900, data: "" },
  { weight: 400, data: "" },
];

export const SORA_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 500, data: "" },
  { weight: 600, data: "" },
  { weight: 800, data: "" },
  { weight: 900, data: "" },
];

export const SPACE_GROTESK_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 500, data: "" },
  { weight: 600, data: "" },
  { weight: 800, data: "" },
  { weight: 900, data: "" },
];

// Fonte Anton (OFL, Google Fonts) — condensada bem pesada, estilo
// 'Impact', usada no layout Brutalismo Editorial (Fase 3).
export const ANTON_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 400, data: "" },
];

// Fonte IBM Plex Mono (OFL, Google Fonts) — monoespaçada técnica, usada
// nos rótulos/rodapé do layout Brutalismo Editorial e Swiss Mono (Fase 3).
// Trocada da Space Mono: o glifo do '@' na Space Mono saía desalinhado
// (menor/mais baixo) comparado ao resto do texto maiúsculo.
export const IBM_PLEX_MONO_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 400, data: "" },
  { weight: 700, data: "" },
];

/** Fontes selecionaveis em Ajustes > Template da marca (renderizacao das artes) */
export const DM_SERIF_DISPLAY_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 400, data: "" },
];

export const VARELA_ROUND_BUFFERS_BASE64: { weight: number; data: string }[] = [
  { weight: 400, data: "" },
];

export const POST_FONTS = [
  { key: "inter", label: "Inter (neutra)", family: FONT_FAMILY, buffers: FONT_BUFFERS_BASE64 },
  { key: "sora", label: "Sora (geometrica)", family: "Sora", buffers: SORA_BUFFERS_BASE64 },
  { key: "space-grotesk", label: "Space Grotesk (tech)", family: "Space Grotesk", buffers: SPACE_GROTESK_BUFFERS_BASE64 },
] as const;

export type PostFontKey = (typeof POST_FONTS)[number]["key"];

/** Fontes de uso interno dos LAYOUTS alternativos (Fase 3 — Brutalismo,
 * Serif Luxe etc.) — não aparecem no seletor de fonte geral (POST_FONTS
 * é 1 família pra tudo); cada layout usa a combinação que precisa. */
export const LAYOUT_FONTS = [
  { key: 'anton', family: 'Anton', buffers: ANTON_BUFFERS_BASE64 },
  { key: 'ibm-plex-mono', family: 'IBM Plex Mono', buffers: IBM_PLEX_MONO_BUFFERS_BASE64 },
  { key: 'dm-serif-display', family: 'DM Serif Display', buffers: DM_SERIF_DISPLAY_BUFFERS_BASE64 },
  { key: 'varela-round', family: 'Varela Round', buffers: VARELA_ROUND_BUFFERS_BASE64 },
] as const;


/** Resolve a familia (nome usado no font-family do SVG) a partir da chave salva em Ajustes */
export function resolvePostFontFamily(key: string | null | undefined): string {
  return POST_FONTS.find((f) => f.key === key)?.family ?? FONT_FAMILY;
}
